SELECT DATE_TRUNC('MONTH', products.launch_date) AS launch_month, COUNT(*) AS store_sale_count FROM store_sales RIGHT OUTER JOIN products ON store_sales.product_id = products.id JOIN suppliers ON suppliers.id = products.supplier_id WHERE products.category = 'Grocery' GROUP BY DATE_TRUNC('MONTH', products.launch_date) HAVING COUNT(*) > 1 ORDER BY launch_month, store_sale_count DESC
